  settings_search_idx_off: 'Lebender Index aus: Die Liste ist leer und bleibt leer. Xenon indiziert nichts, und die Karte des Widgets Speicherplatz bleibt ebenfalls leer.',
  settings_search_idx_capped: 'Limit erreicht: Xenon fügt keine Dateien mehr hinzu, die Suche sieht also nicht alle. Entferne einen Ordner aus der Liste oben, oder gib gezielte Ordner an statt ganzer Laufwerke.',
  settings_search_idx_capped_roots: 'Nicht erfasst:',
  settings_search_idx_near_cap: 'Der Index ist bei {pct}% seines Limits ({max} Dateien): wachsen sie weiter, fügt Xenon keine mehr hinzu und die Suche sieht nicht alle. Entferne einen Ordner aus der Liste oben, oder gib gezielte Ordner an statt ganzer Laufwerke.',
  settings_search_idx_fda: 'macOS hat Xenon den Festplattenvollzugriff entzogen. Das passiert bei jedem Update, weil die Berechtigung an die Signatur der App gebunden ist. Solange sie fehlt, indiziert Xenon deinen Benutzerordner nicht – sonst würde macOS bei jedem Durchlauf nach Schreibtisch, Dokumente, Downloads, Fotos und Musik fragen. Schalte ihn wieder ein unter Systemeinstellungen → Datenschutz & Sicherheit → Festplattenvollzugriff: Xenon aus der Liste entfernen und neu hinzufügen.',
  disk_fda_title: 'macOS hat Xenon eine Berechtigung entzogen',
  disk_fda_text: 'Nach jedem Update entzieht macOS Xenon den Festplattenvollzugriff. Ohne ihn bleiben die Festplattenkarte und die Suche leer. Wieder einschalten: Xenon aus der Liste entfernen und neu hinzufügen.',
