  settings_bg_code_frozen_gpu: 'Auf diesem PC bleibt der Hintergrund nach ein paar Sekunden stehen: Er hat zwei Grafikkarten und Xenon zeichnet auf der integrierten. Das liegt nicht an deinem Code. Du kannst es unter Darstellung, Oberfläche mit „Animationen bei Hybrid-GPU reduzieren“ ändern.',
