  settings_bg_code_help_title: 'So schreibst du den Code',
  settings_bg_code_help_contract: 'Definiere eine Funktion draw(ctx, t, w, h): ctx ist der 2D-Kontext des Canvas, t die vergangenen Sekunden, w und h die Größe in Pixeln. Sie wird mit der unter „Bilder pro Sekunde“ gewählten Frequenz aufgerufen (Standard 30, bis 60). Deklariere Partikel oder Zustand mit const/let über der Funktion, damit sie zwischen Bildern erhalten bleiben.',
