  settings_bg_code_note: 'Der Code zeichnet ein Vollbild-Canvas und läuft in einer isolierten Sandbox: kein Netzwerk, kein Zugriff auf Dashboard, Dateien oder Einstellungen. Vertrag: definiere function draw(ctx, t, w, h), ctx ist der 2D-Kontext, t die vergangenen Sekunden, w und h die Größe in Pixeln. Importiere Hintergründe nur von Personen, denen du vertraust.',
