  streaming_discord_desc: 'Verknüpfe dein Konto, um Discord-Sprache vom Deck aus zu steuern (stummschalten, Ton aus, Kanäle betreten/verlassen).',
  streaming_setup_discord: 'Erstelle eine Discord-App (Developer Portal), füge unter OAuth2 den Redirect http://localhost hinzu und füge hier Client ID und Client Secret ein. Die Discord-Desktop-App muss laufen.',
  streaming_discord_authorize: 'Öffne Discord und klicke im erscheinenden Fenster auf „Autorisieren“.',
  streaming_discord_notrunning: 'Discord-Desktop-App nicht erkannt. Öffne Discord und versuche es erneut.',
  streaming_discord_busy: 'Die lokale Verbindung von Discord ist belegt (möglicherweise nutzt sie eine andere App). Warte einen Moment und drücke erneut auf Verbinden.',
  streaming_discord_pipedenied: 'Discord läuft als Administrator, deshalb darf Xenon nicht mit ihm sprechen. Beende Discord vollständig (Symbol im Infobereich → Beenden), öffne es normal und drücke dann auf Verbinden. Warten hilft nicht.',
  streaming_discord_closed: 'Discord hat die Verbindung geschlossen. Prüfe, ob die Client ID stimmt und ob die Discord-Desktop-App mit dem Konto angemeldet ist, das diese Anwendung erstellt hat.',
  streaming_discord_denied: 'Die Autorisierung wurde in Discord abgelehnt. Bestätige die Anfrage, und stelle sicher, dass du mit dem Konto angemeldet bist, dem die Anwendung gehört.',
  streaming_discord_timeout: 'Das Autorisierungsfenster ist abgelaufen. Versuche es erneut und klicke in Discord zügig auf „Autorisieren“.',
  streaming_token_failed: 'Anmeldung beim Austausch des Codes fehlgeschlagen. Prüfe das Client Secret und ob die Redirect-URL exakt http://localhost lautet.',
  streaming_discord_inflight: 'Eine Anmeldung wartet bereits auf Bestätigung: suche das Pop-up in Discord (oder warte, bis es abläuft), bevor du es erneut versuchst.',
  streaming_discord_badclientid: 'Discord hat die Client ID abgelehnt. Kopiere die „Application ID“ von der Seite General Information deiner App im Developer Portal und gib sie unter Zugangsdaten bearbeiten erneut ein.',
  streaming_discord_authfailed: 'Discord hat die Autorisierung verweigert. Die Discord-Desktop-App muss mit demselben Konto angemeldet sein, dem diese Anwendung im Developer Portal gehört.',
  streaming_discord_invalidscope: 'Discord hat die angeforderten Berechtigungen abgelehnt. Der hier nötige „rpc“-Zugriff wird nur dem Konto gewährt, dem die Anwendung GEHÖRT (oder einem, das du unter den OAuth2-Testern der App hinzugefügt hast): prüfe, mit welchem Konto die Discord-Desktop-App angemeldet ist. Discord verweigert ihn außerdem, wenn deine App eine Activity ist (Flag „Embedded App“). Der Redirect spielt bei diesem Fehler keine Rolle.',
  streaming_discord_badsecret: 'Discord hat das Client Secret abgelehnt. Öffne deine App im Developer Portal, setze das Secret zurück und füge den neuen Wert unter Zugangsdaten bearbeiten ein.',
  streaming_discord_network: 'Discord hat autorisiert, aber dieser PC konnte discord.com nicht erreichen, um die Anmeldung abzuschließen. Prüfe VPN-, Firewall- oder Proxy-Einstellungen und drücke erneut auf Verbinden.',
  streaming_discord_id_shape: 'Das sieht nicht nach einer Discord Client ID aus: sie ist die lange Zahl mit der Bezeichnung „Application ID“ auf der Seite General Information deiner App (nicht der Public Key und nicht das Client Secret).',
