  'remote.intro_title': 'Sichere Fernsteuerung des PCs',
  'remote.intro_p1': 'Damit greifst du vom Smartphone oder Tablet über dein privates Tailscale-Netzwerk (Peer-to-Peer-VPN) auf den Desktop deines PCs zu. Das Video-Streaming übernimmt Sunshine; der kostenlose Moonlight-Client läuft auf deinem Telefon.',
  'remote.intro_p2': 'Sunshine und Tailscale werden über winget (den offiziellen Paketmanager von Microsoft) direkt aus ihren offiziellen Quellen installiert.',
  'remote.intro_p3': 'Der Dashboard-Server ist nie aus dem Internet erreichbar. Die Verbindung bleibt komplett in deinem Tailscale-Netzwerk.',
