  surface_reading: 'Die Bildschirme dieses PCs werden gelesen…',
  surface_mode_both: 'Auf dem Handy und auch auf diesem PC',
  surface_mode_both_hint: 'Das Dashboard öffnet sich auf dem gekoppelten Handy und weiterhin auch hier.',
  ra_guide_open: 'Schritt-für-Schritt-Anleitung',
  ra_guide_title: 'Das Handy einrichten, Schritt für Schritt',
  ra_guide_close: 'Anleitung schließen',
  ra_guide_sub: 'Schritt 1 bis 3 bringen das Dashboard zu Hause aufs Handy. Der Rest wird nur gebraucht, wenn es auch unterwegs funktionieren soll.',
  ra_guide_group_home: 'Zu Hause, im eigenen WLAN',
  ra_guide_group_away: 'Unterwegs (optional)',
  ra_guide_ack: 'Erledigt',
  ra_guide_undo: 'Noch nicht',
  ra_guide_s1: 'Zugriff von anderen Geräten einschalten',
  ra_guide_s1_body: 'Es ist aus, bis du es einschaltest. Solange es aus ist, antwortet Xenon diesem PC und sonst niemandem.',
  ra_guide_s2: 'Mit dem Handy auf den QR-Code halten',
  ra_guide_s2_body: 'Der Code ist eine Einladung, kein Passwort: Er gilt drei Minuten und wird nach ein paar Fehlversuchen ungültig. Das Dashboard öffnet sich im Browser des Handys. Auf dem Handy ist nichts zu installieren.',
  ra_guide_s2_wait: 'Verfügbar, sobald der Schalter oben an ist.',
  ra_guide_s3: 'Zum Startbildschirm des Handys hinzufügen',
  ra_guide_s3_body: 'Auf dem iPhone auf Teilen und dann Zum Home-Bildschirm. Auf Android bietet Chrome die Installation an. Danach öffnet sich Xenon mit eigenem Symbol im Vollbild, und dort funktionieren Mikrofon und Benachrichtigungen.',
  ra_guide_s4: 'Die sichere Adresse einschalten',
  ra_guide_s4_body: 'Das gibt diesem PC einen eigenen Namen, der von überall funktioniert, über eine verschlüsselte Verbindung. Dafür wird Tailscale genutzt, das kostenlos ist, und Xenon installiert es und meldet sich für dich an. Du legst kein Konto bei Xenon an.',
  ra_guide_s5: 'HTTPS-Zertifikate im Tailscale-Konto einschalten',
  ra_guide_s5_body: 'Das ist der einzige Schritt, den Xenon nicht für dich erledigen kann. Öffne die Tailscale-Konsole, scrolle zu HTTPS Certificates und drücke Enable. Das ist in jedem Tarif kostenlos. Danach zurück hierher: Xenon hat weiter gewartet.',
  ra_guide_s6: 'Tailscale mit demselben Konto aufs Handy',
  ra_guide_s6_body: 'Aus dem App Store oder von Google Play holen, mit demselben Konto anmelden, das du gerade benutzt hast, und den Schalter einschalten. Das ist der Schritt, den alle vergessen. Fehlt er, sagt das Handy, dass es die Adresse gar nicht öffnen kann: Es ist nichts kaputt, diese Adresse gibt es nur innerhalb deines eigenen Netzes.',
  ra_guide_s7: 'Das Handy auf der neuen Adresse erneut koppeln',
  ra_guide_s7_body: 'In Schritt 2 auf Gerät hinzufügen drücken und noch einmal scannen. Der Browser bindet eine Kopplung an die Adresse, auf der sie entstanden ist: Ein zu Hause gekoppeltes Handy ist auf der sicheren Adresse nicht gekoppelt. Danach reicht die neue Adresse, zu Hause und unterwegs.',
  ra_guide_done_title: 'Die Einrichtung ist fertig',
  ra_guide_done_body: 'Das Handy ist gekoppelt. Zuletzt: Soll Xenon sich auch weiter auf diesem PC öffnen?',
  ra_guide_keep: 'Auch hier behalten',
  ra_guide_hide: 'Xenon auf diesem PC ausblenden',
  ra_guide_hide_note: 'Ausgeblendet öffnet sich Xenon auf diesem PC nicht mehr, auch nicht bei der Anmeldung. Es läuft im Hintergrund weiter, das Handy funktioniert also unverändert. Das Fenster holst du über das Xenon-Symbol neben der Uhr zurück, oder über Einstellungen und dann Bildschirm.',
  ra_guide_hide_browser: 'Das ist das Dashboard in einem Browser, es gibt also kein Fenster zum Ausblenden. In der Xenon-App kannst du auch festlegen, dass es sich auf diesem PC nicht mehr öffnet.',
  settings_stack: 'Anordnung der Kacheln',
