  settings_supporter_title: 'Unterstützer-Code',
  settings_supporter_lead: 'Hier hinterlegt musst du ihn nie wieder einfügen: Unterstützer-Drops schaltest du mit einem Tippen frei. Er bleibt auf diesem PC und wird nie an deine anderen Bildschirme geschickt.',
  settings_supporter_save: 'Speichern',
  settings_supporter_forget: 'Entfernen',
  settings_supporter_saved: 'Er bleibt auf diesem PC und wird automatisch verwendet, wenn du einen Drop freischaltest.',
  settings_supporter_note: 'Geprüft wird der Code beim Freischalten eines Drops, nicht hier: ein Tippfehler zeigt sich also erst dann. Er gilt, solange dein Unterstützer-Zeitraum läuft, auf bis zu 3 Geräten, und was du bereits freigeschaltet hast, bleibt dir.',
